<?php

// Script to add CSS lessons 21-40 to the Ferga section in Firebase
$firebaseUrl = 'https://ai-platform-adb1b-default-rtdb.firebaseio.com/';
$idToken = trim(file_get_contents('/tmp/opencode/fb_token.txt'));
$langId = '-OyrwFaGbQ7K-1QnzHvq';

function fbPost($url, $data) {
    global $idToken;
    $ch = curl_init($url . '?auth=' . urlencode($idToken));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
    curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/json']);
    $res = curl_exec($ch);
    curl_close($ch);
    return $res;
}

function lesson($order, $level_so, $level_ba, $title_so, $title_ba, $content_so, $content_ba, $code) {
    return [
        'order' => $order,
        'level_so' => $level_so,
        'level_ba' => $level_ba,
        'title_so' => $title_so,
        'title_ba' => $title_ba,
        'content_so' => $content_so,
        'content_ba' => $content_ba,
        'code' => $code,
        'example_output' => '',
        'challenge_desc_so' => '',
        'challenge_desc_ba' => '',
        'expected_output' => '',
    ];
}

